O=[row[:] for row in G]
seed=[(r,c,G[r][c]) for r in range(3,7) for c in range(4,9) if G[r][c]!=4]
anchors={
 'TR':(5,20,2,'h'),
 'BL':(19,4,4,'v'),
 'BR':(20,19,2,'hv')}
for name,(ar,ac,side,ori) in anchors.items():
    k=side//2
    for sr,sc,v in seed:
        if v==2: continue
        q,p=sr-5,sc-5
        if 'v' in ori: q=1-q
        if 'h' in ori: p=1-p
        rr,cc=ar+q*k,ac+p*k
        for dr in range(k):
            for dc in range(k):
                r,c=rr+dr,cc+dc
                assert 0<=r<N and 0<=c<N, (name,sr,sc,v,r,c)
                # ensure no collision with a non-background, non-target object
                if O[r][c]!=4 and not (O[r][c]==2 and v==2):
                    print('collision', name,(r,c),O[r][c],v)
                O[r][c]=v
print('\n'.join(' '.join(map(str,row)) for row in O))
